/*
 * A041135  Denominators of continued fraction convergents to sqrt(76).
 * https://oeis.org/A041135
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, frac, easy
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 11, u32 n <= 23, u64 n <= 47, u128 n <= 92,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  Sequence A041135: denominators of continued‑fraction convergents to sqrt(76)
 *
 *  The sequence can be generated by the recurrence
 *      q(0) = 1
 *      q(k) = a(k) * q(k-1) + q(k-2)   (k ≥ 1)
 *  where a(0) = 8 and the remaining partial quotients a(k) (k≥1) repeat
 *  the 12‑term period [1,2,1,1,5,4,5,1,1,2,1,16].
 *
 *  The code keeps a cache of all values computed so far and extends it
 *  lazily on demand.  No values are hard‑coded except the small period
 *  of the continued fraction.
 */

#include <stdlib.h>

static const int cf_period[12] = { 1, 2, 1, 1, 5, 4, 5, 1, 1, 2, 1, 16 };
static const int cf_period_len = 12;   /* period length of sqrt(76) CF */
static const int a0 = 8;               /* the non‑periodic first partial quotient */

static seq_t *cache    = NULL;  /* cache of computed denominators q(k) */
static size_t cache_cap = 0;    /* allocated capacity (in terms of q(k)) */
static size_t cache_size = 0;   /* highest index + 1 that is valid in cache */

/* extend cache so that it can hold at least 'need' elements */
static void ensure_cache_capacity(size_t need)
{
    if (need <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap : 1;
    while (new_cap < need)
        new_cap <<= 1;                 /* double until big enough */
    seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
    cache = tmp;
    cache_cap = new_cap;
}

/* initialise the cache with the first term q(0) = 1 */
static void init_cache(void)
{
    if (cache != NULL)
        return;                       /* already initialised */
    ensure_cache_capacity(1);
    cache[0] = (seq_t)1;
    cache_size = 1;
}

seq_t a(idx_t n)
{
    /* trivial case  */
    if (n == 0)
        return (seq_t)1;

    /* initialise on first call */
    if (cache == NULL)
        init_cache();

    if ((size_t)n < cache_size)
        return cache[(size_t)n];        /* already computed */

    /* need to compute new terms up to n */
    ensure_cache_capacity((size_t)n + 1);

    /* indices of the last two computed denominators */
    seq_t prev2, prev1;
    if (cache_size >= 2) {
        prev2 = cache[cache_size - 2];
        prev1 = cache[cache_size - 1];
    } else {
        /* cache_size == 1  ->  only q(0) is known, q(-1) = 0 */
        prev2 = (seq_t)0;
        prev1 = cache[0];
    }

    /* compute from the first missing index up to n */
    for (idx_t k = (idx_t)cache_size; k <= n; ++k) {
        /* partial quotient a(k) for k ≥ 1 :  a(k) = cf_period[(k-1) % period] */
        int idx = (int)((k - 1) % cf_period_len);
        seq_t ak = (seq_t)cf_period[idx];

        /* recurrence: q(k) = a(k) * q(k-1) + q(k-2) */
        seq_t qk = ak * prev1 + prev2;

        cache[(size_t)k] = qk;

        /* shift the two previous terms for the next iteration */
        prev2 = prev1;
        prev1 = qk;
    }

    cache_size = (size_t)n + 1;
    return cache[(size_t)n];
}
